#!/usr/bin/env node
/**
 * Generate CommonMark spec conformance tests from spec.json.
 *
 * Usage: node scripts/gen-spec-tests.js [--no-skip]
 *
 * Unlike `gen-tests.js` (which compares our Markdown serialization with
 * remark), these tests assert that `md_to_html` produces exactly the HTML the
 * CommonMark spec prescribes for every example in the spec.
 *
 * The generated files live in `src/spec_tests/` and are git-ignored; only this
 * generator and its skip list are checked in.
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

const noSkip = process.argv.includes('--no-skip');

const SPEC_VERSION = '0.31.2';
const SPEC_URL = `https://spec.commonmark.org/${SPEC_VERSION}/spec.json`;
const OUTPUT_DIR = path.join(__dirname, '../src/spec_tests');

// Examples that do not pass yet, grouped by spec section. Every entry here is
// a known gap in the parser, not an intentional deviation: the goal is for this
// table to stay empty.
const SKIP_TESTS = {
  "Tabs": [1, 2, 4, 5, 6, 7, 8, 9],
  "Backslash escapes": [21, 23],
  "Entity and numeric character references": [31, 33],
  "Thematic breaks": [48, 49, 60, 61],
  "ATX headings": [63, 64, 69, 70],
  "Setext headings": [81, 82, 87, 93, 95, 96, 98],
  "Indented code blocks": [108, 109, 112],
  "Fenced code blocks": [138, 145],
  "HTML blocks": [148, 150, 162, 163, 164, 165, 166, 167, 169, 170, 171, 172, 173, 175, 176, 178, 180, 181, 182, 183, 184, 185, 191],
  "Link reference definitions": [193, 194, 195, 197, 199, 201, 202, 208, 209, 210, 214, 215, 216, 217],
  "Block quotes": [231, 232, 233, 238, 247, 250, 251],
  "List items": [254, 256, 258, 259, 262, 263, 264, 270, 271, 273, 274, 277, 278, 279, 283, 285, 286, 287, 288, 289, 290, 291, 292, 293, 294, 296, 297, 298, 299, 300],
  "Lists": [304, 307, 309, 312, 313, 315, 316, 317, 318, 319, 320, 321, 323, 324, 325, 326],
  "Code spans": [347],
  "Emphasis and strong emphasis": [353, 354, 367],
  "Links": [526, 538, 540, 541, 546, 551, 565, 570],
  "Autolinks": [599, 603],
};

function shouldSkip(section, example) {
  if (noSkip) return false;
  const list = SKIP_TESTS[section];
  return list !== undefined && list.includes(example);
}

/** Escape a string so it can be embedded in a MoonBit string literal. */
function escapeString(s) {
  let out = '';
  for (const ch of s) {
    const code = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === '"') out += '\\"';
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (code < 0x20 || code === 0x7f) out += `\\u{${code.toString(16)}}`;
    else out += ch;
  }
  return out;
}

function sectionToId(section) {
  return section
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_|_$/g, '');
}

const PKG = `import {
  "mizchi/markdown",
}
`;

const HELPER = `///| CommonMark ${SPEC_VERSION} conformance tests.
///|
///| Generated by \`scripts/gen-spec-tests.js\` from
///| <https://spec.commonmark.org/${SPEC_VERSION}/spec.json>. Do not edit by hand.

///|
/// Assert that rendering \`input\` produces exactly the HTML the CommonMark spec
/// prescribes. Bare-URL autolinking is a GFM extension, so it is turned off
/// here to keep the comparison to plain CommonMark.
pub fn assert_spec(input : String, expected : String) -> Unit {
  let actual = @markdown.md_to_html(input, autolink=false)
  if actual != expected {
    println("=== input ===")
    println(input)
    println("=== expected ===")
    println(expected)
    println("=== actual ===")
    println(actual)
    panic()
  }
}
`;

async function loadSpec() {
  const cache = path.join(__dirname, '../node_modules/.cache/commonmark-spec.json');
  if (fs.existsSync(cache)) {
    return JSON.parse(fs.readFileSync(cache, 'utf8'));
  }
  console.log(`Fetching CommonMark ${SPEC_VERSION} spec...`);
  const response = await fetch(SPEC_URL);
  const spec = await response.json();
  fs.mkdirSync(path.dirname(cache), { recursive: true });
  fs.writeFileSync(cache, JSON.stringify(spec));
  return spec;
}

async function main() {
  const spec = await loadSpec();
  console.log(`Found ${spec.length} examples`);

  fs.rmSync(OUTPUT_DIR, { recursive: true, force: true });
  fs.mkdirSync(OUTPUT_DIR, { recursive: true });
  fs.writeFileSync(path.join(OUTPUT_DIR, 'moon.pkg'), PKG);
  fs.writeFileSync(path.join(OUTPUT_DIR, 'helper.mbt'), HELPER);

  const bySection = new Map();
  for (const test of spec) {
    if (!bySection.has(test.section)) bySection.set(test.section, []);
    bySection.get(test.section).push(test);
  }

  let total = 0;
  let skipped = 0;
  for (const [section, tests] of bySection) {
    let content = `///| CommonMark spec tests: ${section}\n\n`;
    for (const test of tests) {
      if (shouldSkip(section, test.example)) {
        content += `#skip("not conformant yet")\n`;
        skipped++;
      }
      content += `test "commonmark ${test.example}: ${section}" {\n`;
      content += `  assert_spec("${escapeString(test.markdown)}", "${escapeString(test.html)}")\n`;
      content += `}\n\n`;
      total++;
    }
    fs.writeFileSync(path.join(OUTPUT_DIR, `${sectionToId(section)}_test.mbt`), content);
  }

  const passing = total - skipped;
  console.log(
    `Generated ${total} tests in ${OUTPUT_DIR} ` +
      `(${passing} active, ${skipped} skipped, ${((passing / total) * 100).toFixed(1)}% coverage)`
  );
  console.log('Run them with: moon test src/spec_tests --target js');
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
